27	fn decode_revert_reason(err_msg: &str) -> Option<String> {
28	    let data_prefix = "data: \"0x";
29	    let start = err_msg.find(data_prefix)? + data_prefix.len();
30	    let end = err_msg[start..].find('"')? + start;
31	    let hex_data = &err_msg[start..end];
32	
33	    if hex_data.is_empty() {
34	        return Some("(empty)".to_string());
35	    }
36	
37	    if hex_data.len() < 8 {
38	        return Some(format!("0x{}", hex_data));
39	    }
40	
41	    let bytes = alloy::hex::decode(hex_data).ok()?;
42	
43	    if bytes.len() >= 4 && bytes[0..4] == [0x08, 0xc3, 0x79, 0xa0] {
44	        if bytes.len() >= 68 {
45	            let offset = u32::from_be_bytes([bytes[4 + 28], bytes[4 + 29], bytes[4 + 30], bytes[4 + 31]]) as usize;
46	            if bytes.len() >= 36 + offset {
47	                let len_start = 4 + offset;
48	                let len = u32::from_be_bytes([bytes[len_start + 28], bytes[len_start + 29], bytes[len_start + 30], bytes[len_start + 31]]) as usize;
49	                let str_start = len_start + 32;
50	                if bytes.len() >= str_start + len {
51	                    return String::from_utf8(bytes[str_start..str_start + len].to_vec()).ok();
52	                }
53	            }
54	        }
55	    }
56	
57	    if bytes.len() >= 4 && bytes[0..4] == [0x4e, 0x48, 0x7b, 0x71] {
58	        if bytes.len() >= 36 {
59	            let code = U256::from_be_slice(&bytes[4..36]);
60	            return Some(format!("Panic(0x{:02x})", code));
61	        }
62	    }
63	
64	    if bytes.len() >= 4 {
65	        let selector: [u8; 4] = bytes[0..4].try_into().unwrap();
66	        let known_errors: &[(&str, usize)] = &[
67	            ("UnknownRoot(bytes32)", 32),
68	            ("AlreadySpent()", 0),
69	            ("ProofTooLong(uint256)", 32),
70	            ("NotOutbox(address)", 32),
71	        ];
72	        for (sig, param_len) in known_errors {
73	            let expected = &alloy::primitives::keccak256(sig)[..4];
74	            if selector == expected {
75	                if *param_len == 0 {
76	                    return Some(sig.to_string());
77	                } else if bytes.len() >= 4 + param_len {
78	                    return Some(format!("{}(0x{})", sig.split('(').next().unwrap(), alloy::hex::encode(&bytes[4..4 + param_len])));
79	                }
80	            }
81	        }
82	    }
83	
84	    Some(format!("0x{}", hex_data))
85	}
