87	pub async fn was_event_emitted(
88	    provider: &DynProvider<Ethereum>,
89	    address: Address,
90	    event_sig: &str,
91	    epoch: u64,
92	) -> bool {
93	    let current_block = match provider.get_block_number().await {
94	        Ok(b) => b,
95	        Err(_) => return false,
96	    };
97	    let from_block = current_block.saturating_sub(500);
98	
99	    let sig = alloy::primitives::keccak256(event_sig);
100	    let filter = Filter::new()
101	        .address(address)
102	        .event_signature(sig)
103	        .from_block(from_block)
104	        .to_block(from_block + 1000);
105	
106	    match provider.get_logs(&filter).await {
107	        Ok(logs) => logs.iter().any(|log| {
108	            log.topics().get(1)
109	                .map(|t| U256::from_be_bytes(t.0).to::<u64>() == epoch)
110	                .unwrap_or(false)
111	        }),
112	        Err(_) => false,
113	    }
114	}
