132	/// Sentinel: our transaction is mined but not durable yet. Keep the task, change nothing,
133	/// and come back next cycle - do **not** send anything at this nonce again.
134	///
135	/// Distinct from `"PendingReplacement"` on purpose. That one means "still in the mempool,
136	/// replace it with a higher fee next cycle"; this one means "already on chain, replacing
137	/// it would be a duplicate". Matched by exact string in `dispatcher.rs` and
138	/// `epoch_watcher.rs`, like every other sentinel in this crate.
139	pub const AWAITING_FINALITY: &str = "AwaitingFinality";
140	
141	/// Sentinels meaning "this transaction is still ours": either in the mempool
142	/// (`PendingReplacement`) or mined but not yet durable ([`AWAITING_FINALITY`]).
143	///
144	/// A task must return these untouched instead of falling through to its "did someone else
145	/// do it?" checks. Those read the chain, and for a mined-but-not-durable transaction they
146	/// would find *our own* effect, read it as a lost race, and retire the task - which is the
147	/// exact hole the durability gate closes.
148	pub fn is_in_flight(err: &(dyn std::error::Error + Send + Sync)) -> bool {
149	    let msg = err.to_string();
150	    msg == "PendingReplacement" || msg == AWAITING_FINALITY
151	}
