153	/// How durable a write has to be before [`send_or_replace`] reports success.
154	///
155	/// One confirmation is not durability: the dispatcher retires a task the moment its
156	/// action returns `Ok(())`, so a transaction reorged out after that confirmation is never
157	/// re-sent and never re-observed.
158	#[derive(Clone)]
159	pub enum Durability {
160	    /// One confirmation, no gate.
161	    ///
162	    /// Only for writes whose caller re-derives its own state from the chain on every
163	    /// cycle, so a gate here would be escaped immediately and would leave an uncleared
164	    /// pending record behind. `claim` is the sole case - see `tasks/claim.rs`.
165	    Confirmed,
166	    /// The sending chain's own `finalized` tag has reached the receipt's block.
167	    ///
168	    /// The bar for every settlement-chain write: Ethereum and Gnosis both finalize under
169	    /// their own consensus, and their `finalized` tag is exactly "cannot be reorged".
170	    ChainFinalized,
171	    /// Arbitrum L2: the receipt's block sits in a sequencer batch whose L1 posting block
172	    /// is finalized.
173	    ///
174	    /// An L2 block is only as durable as the L1 batch carrying it, so the raw L2
175	    /// `finalized` tag is not the bar here - see [`crate::finality::is_l2_block_finalized`].
176	    ArbitrumBatchFinalized {
177	        l1_provider: DynProvider<Ethereum>,
178	        sequencer_inbox: Option<Address>,
179	    },
180	}
181	
182	impl Durability {
183	    /// Whether a receipt in `receipt_block` on `provider`'s chain clears this bar.
184	    async fn is_durable(
185	        &self,
186	        provider: &DynProvider<Ethereum>,
187	        receipt_block: u64,
188	    ) -> Result<bool, Box<dyn std::error::Error + Send + Sync>> {
189	        match self {
190	            Durability::Confirmed => Ok(true),
191	            Durability::ChainFinalized => {
192	                let finalized = provider
193	                    .get_block_by_number(alloy::eips::BlockNumberOrTag::Finalized)
194	                    .await?
195	                    .map(|block| block.header.number);
196	                Ok(block_is_finalized(receipt_block, finalized))
197	            }
198	            Durability::ArbitrumBatchFinalized { l1_provider, sequencer_inbox } => {
199	                crate::finality::is_l2_block_finalized(receipt_block, provider, l1_provider, *sequencer_inbox).await
200	            }
201	        }
202	    }
203	}
