205	/// The settlement-chain bar: a receipt is durable once the chain's own `finalized` tag has
206	/// reached its block.
207	///
208	/// `None` is "the node served no finalized block" - an RPC that cannot answer is not
209	/// evidence of durability, so it counts as not durable and the caller waits.
210	const fn block_is_finalized(receipt_block: u64, finalized_block: Option<u64>) -> bool {
211	    match finalized_block {
212	        Some(finalized) => finalized >= receipt_block,
213	        None => false,
214	    }
215	}
