217	/// What the chain's answer about an already-broadcast nonce means for the task.
218	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
219	enum MinedOutcome {
220	    /// Mined, succeeded, durable: the write is done for good.
221	    Settled,
222	    /// Mined and succeeded, but still reorgable: wait, and do not touch the nonce.
223	    AwaitFinality,
224	    /// Mined and reverted. Terminal: the nonce is spent, so a retry needs a fresh one.
225	    Reverted,
226	    /// No receipt at all - never mined, or reorged back out. Send again at the same nonce.
227	    Resend,
228	}
229	
230	/// `receipt` is `None` when the chain has no receipt for the transaction we broadcast, and
231	/// `Some((succeeded, durable))` when it has one.
232	///
233	/// A reverted receipt is terminal whether or not it is durable: the revert consumed the
234	/// nonce, so there is nothing to wait for, and the caller's own post-revert checks decide
235	/// what happens next.
236	const fn mined_outcome(receipt: Option<(bool, bool)>) -> MinedOutcome {
237	    match receipt {
238	        None => MinedOutcome::Resend,
239	        Some((false, _)) => MinedOutcome::Reverted,
240	        Some((true, false)) => MinedOutcome::AwaitFinality,
241	        Some((true, true)) => MinedOutcome::Settled,
242	    }
243	}
244	
245	/// What the chain currently says about a transaction we broadcast.
246	///
247	/// Every uncertainty resolves to [`MinedOutcome::AwaitFinality`] rather than
248	/// [`MinedOutcome::Resend`]: an RPC that will not answer is not evidence that a
249	/// transaction is absent, and waiting another cycle is always recoverable where re-sending
250	/// over a mined write is not.
251	async fn broadcast_outcome(
252	    provider: &DynProvider<Ethereum>,
253	    hash: FixedBytes<32>,
254	    durability: &Durability,
255	    action: &str,
256	    route_name: &str,
257	) -> MinedOutcome {
258	    let receipt = match provider.get_transaction_receipt(hash).await {
259	        Ok(receipt) => receipt,
260	        Err(e) => {
261	            warn!(logger = "Task", route = route_name, action, "Could not read the receipt ({e}), waiting rather than re-sending");
262	            return MinedOutcome::AwaitFinality;
263	        }
264	    };
265	
266	    let receipt = match receipt {
267	        Some(receipt) => receipt,
268	        // The only path that re-sends: the chain has no receipt, so the transaction either
269	        // never mined or was reorged back out.
270	        None => return MinedOutcome::Resend,
271	    };
272	
273	    let block = match receipt.block_number {
274	        Some(block) => block,
275	        None => {
276	            warn!(logger = "Task", route = route_name, action, "Receipt carries no block number, waiting");
277	            return MinedOutcome::AwaitFinality;
278	        }
279	    };
280	
281	    mined_outcome(Some((receipt.status(), is_durable(provider, durability, block, action, route_name).await)))
282	}
