284	/// [`Durability::is_durable`] with the RPC failure folded in as "not durable yet".
285	///
286	/// A failed durability read must never be reported as durable: that would retire the task
287	/// on exactly the evidence the gate exists to demand.
288	async fn is_durable(
289	    provider: &DynProvider<Ethereum>,
290	    durability: &Durability,
291	    block: u64,
292	    action: &str,
293	    route_name: &str,
294	) -> bool {
295	    match durability.is_durable(provider, block).await {
296	        Ok(durable) => durable,
297	        Err(e) => {
298	            warn!(logger = "Task", route = route_name, action, block, "Durability check failed ({e}), treating as not final");
299	            false
300	        }
301	    }
302	}
