304	/// Apply a [`MinedOutcome`] to the pending record and turn it into what [`send_or_replace`]
305	/// returns; `None` means "not resolved here", i.e. fall through to the replacement path.
306	///
307	/// The pending record is cleared for every terminal outcome and deliberately *kept* for
308	/// [`MinedOutcome::AwaitFinality`]: it is what stops the next cycle from re-sending a
309	/// transaction that is already on chain, and what lets that cycle re-check the very same
310	/// nonce instead of claiming a new one.
311	fn settle(
312	    task_store: &Arc<Mutex<TaskStore>>,
313	    key: &str,
314	    outcome: MinedOutcome,
315	    action: &str,
316	    route_name: &str,
317	) -> Option<Result<(), Box<dyn std::error::Error + Send + Sync>>> {
318	    match outcome {
319	        MinedOutcome::Settled => {
320	            task_store.lock().unwrap().clear_pending_tx(key);
321	            info!(logger = "Task", route = route_name, action, "Transaction succeeded and is final");
322	            Some(Ok(()))
323	        }
324	        MinedOutcome::AwaitFinality => {
325	            info!(logger = "Task", route = route_name, action, "Transaction mined, waiting for it to become final");
326	            Some(Err(AWAITING_FINALITY.into()))
327	        }
328	        MinedOutcome::Reverted => {
329	            task_store.lock().unwrap().clear_pending_tx(key);
330	            Some(Err(format!("[{}] {} reverted", route_name, action).into()))
331	        }
332	        MinedOutcome::Resend => None,
333	    }
334	}
