336	/// Send `call`, or replace this task's in-flight transaction with a fee-bumped one at
337	/// the same nonce.
338	///
339	/// The nonce is pinned on every send, not just replacements. Pinning bypasses alloy's
340	/// `NonceFiller` (its `status()` returns `Finished` once a nonce is set), which is
341	/// correct for a replacement - it reuses a slot rather than claiming a new one - and
342	/// on a first send it means the nonce is known *before* broadcasting. Reading it back
343	/// afterwards would be unreliable: a node that has not yet seen the transaction answers
344	/// null, and losing the nonce would let the next cycle send a duplicate, which is the
345	/// exact failure this function exists to prevent.
346	///
347	/// `Ok(())` means the write cleared `durability`, not merely that it confirmed. Until it
348	/// does, the pending record stays and this returns [`AWAITING_FINALITY`] so the caller's
349	/// task survives to re-check the same nonce. A nonce whose receipt has disappeared is
350	/// re-sent through the usual fee-bump path; one that still has a receipt is never re-sent.
351	pub async fn send_or_replace<P, D>(
352	    call: alloy::contract::CallBuilder<P, D, Ethereum>,
353	    provider: &DynProvider<Ethereum>,
354	    wallet_address: Address,
355	    task_store: &Arc<Mutex<TaskStore>>,
356	    epoch: u64,
357	    action: &str,
358	    route_name: &str,
359	    durability: &Durability,
360	) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
361	where
362	    P: Provider<Ethereum>,
363	    D: alloy::contract::CallDecoder,
364	{
365	    let key = pending_key(action, epoch);
366	    let market = provider.estimate_eip1559_fees().await?;
367	
368	    // Bound to a local so the `MutexGuard` is dropped here rather than being held
369	    // across the awaits below, which would make this future non-`Send`.
370	    let existing = task_store.lock().unwrap().get_pending_tx(&key);
371	
372	    // Re-entry: settle the nonce we already broadcast at before considering a replacement.
373	    // Replacing a transaction that is already mined would duplicate a write that has
374	    // landed - a second deposit, in the case of `challenge`.
375	    //
376	    // A record written before this field existed carries no hash; there is nothing to look
377	    // up, so it takes the replacement path as it always did. Same nonce, so still no
378	    // duplicate.
379	    if let Some(hash) = existing.as_ref().and_then(|previous| previous.tx_hash) {
380	        let outcome = broadcast_outcome(provider, hash, durability, action, route_name).await;
381	        if let Some(result) = settle(task_store, &key, outcome, action, route_name) {
382	            return result;
383	        }
384	        warn!(logger = "Task", route = route_name, action, "Broadcast transaction has no receipt, re-sending at the same nonce");
385	    }
386	
387	    let (nonce, max_fee, priority_fee) = match existing {
388	        Some(previous) => {
389	            let nonce = previous.nonce;
390	            if let Some(blocking) = blocking_nonce(provider, wallet_address).await {
391	                if blocking != nonce {
392	                    info!(logger = "Task", route = route_name, action, nonce, blocking, "Queued behind an earlier nonce, waiting");
393	                    return Err("PendingReplacement".into());
394	                }
395	            }
396	            match (
397	                crate::bumped_fee(previous.max_fee, market.max_fee_per_gas),
398	                crate::bumped_fee(previous.priority_fee, market.max_priority_fee_per_gas),
399	            ) {
400	                (Some(max_fee), Some(priority_fee)) => {
401	                    info!(logger = "Task", route = route_name, action, nonce, max_fee, "Replacing pending tx with a higher fee");
402	                    (nonce, max_fee, priority_fee)
403	                }
404	                _ => {
405	                    warn!(logger = "Task", route = route_name, action, nonce, "Fee ceiling reached, holding rather than bumping further");
406	                    return Err("PendingReplacement".into());
407	                }
408	            }
409	        }
410	        None => {
411	            let nonce = provider.get_transaction_count(wallet_address).pending().await?;
412	            (nonce, market.max_fee_per_gas, market.max_priority_fee_per_gas)
413	        }
414	    };
415	
416	    task_store.lock().unwrap().set_pending_tx(&key, nonce, max_fee, priority_fee);
417	
418	    let sent = call
419	        .nonce(nonce)
420	        .max_fee_per_gas(max_fee)
421	        .max_priority_fee_per_gas(priority_fee)
422	        .send()
423	        .await;
424	
425	    let pending = match sent {
426	        Ok(pending) => {
427	            // Persisted before the receipt is awaited, so a crash while waiting still
428	            // leaves the next run able to look this transaction up instead of re-sending
429	            // over it.
430	            task_store.lock().unwrap().set_pending_tx_hash(&key, *pending.tx_hash());
431	            pending
432	        }
433	        Err(e) => {
434	            let msg = e.to_string();
435	            if msg.contains("nonce too low") {
436	                info!(logger = "Task", route = route_name, action, nonce, "Nonce already consumed, deferring to on-chain checks");
437	                task_store.lock().unwrap().clear_pending_tx(&key);
438	                return Err("NonceConsumed".into());
439	            }
440	            if msg.contains("replacement transaction underpriced") {
441	                warn!(logger = "Task", route = route_name, action, nonce, "Replacement underpriced, bumping further next cycle");
442	                return Err("PendingReplacement".into());
443	            }
444	            // Anything else may or may not have reached a mempool, so the record stays:
445	            // a stale one is harmless, a lost one risks a duplicate.
446	            return send_tx(Err(e), action, route_name).await;
447	        }
448	    };
449	
450	    match pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await {
451	        Ok(receipt) => {
452	            let durable = match receipt.block_number {
453	                Some(block) => is_durable(provider, durability, block, action, route_name).await,
454	                None => false,
455	            };
456	            let outcome = mined_outcome(Some((receipt.status(), durable)));
457	            // `Resend` is unreachable here - we are holding a receipt - and settling is the
458	            // only way the pending record is ever cleared, so falling through would leak it.
459	            settle(task_store, &key, outcome, action, route_name)
460	                .unwrap_or_else(|| Err(AWAITING_FINALITY.into()))
461	        }
462	        Err(e) => {
463	            warn!(logger = "Task", route = route_name, action, nonce, "Receipt not seen ({e}), will replace next cycle");
464	            Err("PendingReplacement".into())
465	        }
466	    }
467	}
468	
469	pub async fn send_tx(
470	    result: Result<PendingTransactionBuilder<Ethereum>, ContractError>,
471	    action: &str,
472	    route_name: &str,
473	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
474	    match result {
475	        Ok(pending) => {
476	            let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;
477	            if !receipt.status() {
478	                return Err(format!("[{}] {} reverted", route_name, action).into());
479	            }
480	            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
481	            Ok(())
482	        }
483	        Err(e) => {
484	            let err_msg = e.to_string();
485	            match decode_revert_reason(&err_msg) {
486	                Some(reason) => {
487	                    error!(logger = "Task", route = route_name, action, reason = reason.as_str(), "Transaction reverted");
488	                    Err(format!("[{}] {} reverted: {}", route_name, action, reason).into())
489	                }
490	                None => Err(e.into()),
491	            }
492	        }
493	    }
494	}
