496	#[derive(Debug, Clone, Serialize, Deserialize)]
497	pub struct Task {
498	    pub epoch: u64,
499	    pub execute_after: u64,
500	    pub kind: TaskKind,
501	}
502	
503	/// A transaction that has been broadcast but not yet seen confirmed.
504	///
505	/// Tracked per route in [`RouteState`] rather than on a [`Task`], because the claim
506	/// that `EpochWatcher` files has no `Task` behind it, and because a task can be
507	/// removed by `invalidate_tasks` while its transaction is still in flight.
508	#[derive(Debug, Clone, Serialize, Deserialize)]
509	pub struct PendingTx {
510	    pub nonce: u64,
511	    pub max_fee: u128,
512	    pub priority_fee: u128,
513	    /// Hash of the last transaction broadcast at this nonce, once it has been broadcast.
514	    ///
515	    /// The only way to ask the chain about a specific transaction: `eth_getTransactionCount`
516	    /// answers about the nonce, not about *our* attempt at it, so the durability gate in
517	    /// [`send_or_replace`] needs the hash to fetch a receipt on re-entry.
518	    ///
519	    /// `None` covers both "recorded, not yet broadcast" and a record written by a version
520	    /// of the bot that predates this field; `send_or_replace` treats both as "nothing to
521	    /// look up" and falls through to a same-nonce re-send.
522	    #[serde(default)]
523	    pub tx_hash: Option<FixedBytes<32>>,
524	}
525	
526	/// Key for [`RouteState::pending_txs`] - one in-flight transaction per action per epoch.
527	pub fn pending_key(action: &str, epoch: u64) -> String {
528	    format!("{action}:{epoch}")
529	}
