531	#[derive(Debug, Clone, Serialize, Deserialize)]
532	#[serde(tag = "type")]
533	pub enum TaskKind {
534	    SaveSnapshot,
535	    Claim { state_root: FixedBytes<32> },
536	    ValidateClaim,
537	    Challenge,
