600	pub struct ClaimStore {
601	    path: PathBuf,
602	}
603	
604	impl ClaimStore {
605	    pub fn new(path: impl Into<PathBuf>) -> Self {
606	        Self { path: path.into() }
607	    }
608	
609	    fn load_all(&self) -> Vec<ClaimData> {
610	        match fs::read_to_string(&self.path) {
611	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse claims file - data corrupted"),
612	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
613	            Err(e) => panic!("Failed to read claims file: {}", e),
614	        }
615	    }
616	
617	    fn save_all(&self, claims: &[ClaimData]) {
618	        if let Some(parent) = self.path.parent() {
619	            fs::create_dir_all(parent).expect("Failed to create claims directory");
620	        }
621	        let contents = serde_json::to_string_pretty(claims).expect("Failed to serialize claims");
622	        fs::write(&self.path, contents).expect("Failed to write claims file");
623	    }
624	
625	    pub fn store(&self, claim: ClaimData) {
626	        let mut claims = self.load_all();
627	        let existing = claims.iter().filter(|c| c.epoch == claim.epoch).count();
628	        if existing > 0 {
629	            panic!("Duplicate claim for epoch {} - this should never happen", claim.epoch);
630	        }
631	        claims.push(claim);
632	        self.save_all(&claims);
633	    }
634	
635	    pub fn update<F>(&self, epoch: u64, f: F)
636	    where
637	        F: FnOnce(&mut ClaimData),
638	    {
639	        let mut claims = self.load_all();
640	        let claim = claims.iter_mut().find(|c| c.epoch == epoch);
641	        match claim {
642	            Some(c) => {
643	                f(c);
644	                self.save_all(&claims);
645	            }
646	            None => panic!("Cannot update claim for epoch {} - not found", epoch),
647	        }
648	    }
649	
650	    pub fn get(&self, epoch: u64) -> ClaimData {
651	        let claims = self.load_all();
652	        let matches: Vec<_> = claims.into_iter().filter(|c| c.epoch == epoch).collect();
653	        match matches.len() {
654	            0 => panic!("No claim found for epoch {}", epoch),
655	            1 => matches.into_iter().next().unwrap(),
656	            n => panic!("Multiple claims ({}) for epoch {} - impossible state", n, epoch),
657	        }
658	    }
659	
660	    pub fn get_claim(&self, epoch: u64) -> Claim {
661	        let c = self.get(epoch);
662	        Claim {
663	            stateRoot: c.state_root,
664	            claimer: c.claimer,
665	            timestampClaimed: c.timestamp_claimed,
666	            timestampVerification: c.timestamp_verification,
667	            blocknumberVerification: c.blocknumber_verification,
668	            honest: match c.honest.as_str() {
669	                "Claimer" => Party::Claimer,
670	                "Challenger" => Party::Challenger,
671	                _ => Party::None,
672	            },
673	            challenger: c.challenger,
674	        }
675	    }
676	
677	    pub fn remove(&self, epoch: u64) {
678	        let mut claims = self.load_all();
679	        claims.retain(|c| c.epoch != epoch);
680	        self.save_all(&claims);
681	    }
682	
683	    pub fn has_state_root_in_recent_claims(&self, state_root: FixedBytes<32>, since_timestamp: u32) -> bool {
684	        let claims = self.load_all();
685	        claims.iter().any(|c| c.state_root == state_root && c.timestamp_claimed >= since_timestamp)
686	    }
687	
688	    pub fn exists(&self, epoch: u64) -> bool {
689	        self.load_all().iter().any(|c| c.epoch == epoch)
690	    }
691	}
