693	pub struct TaskStore {
694	    path: PathBuf,
695	}
696	
697	impl TaskStore {
698	    pub fn new(path: impl Into<PathBuf>) -> Self {
699	        Self { path: path.into() }
700	    }
701	
702	    fn label(&self) -> String {
703	        self.path.file_stem()
704	            .map(|s| s.to_string_lossy().to_uppercase().replace("-", "_"))
705	            .unwrap_or_default()
706	    }
707	
708	    pub fn load(&self) -> RouteState {
709	        match fs::read_to_string(&self.path) {
710	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse schedule file - data corrupted"),
711	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => RouteState::default(),
712	            Err(e) => panic!("Failed to read schedule file: {}", e),
713	        }
714	    }
715	
716	    pub fn save(&self, state: &RouteState) {
717	        if let Some(parent) = self.path.parent() {
718	            fs::create_dir_all(parent).expect("Failed to create schedules directory");
719	        }
720	        let contents = serde_json::to_string_pretty(state).expect("Failed to serialize state");
721	        fs::write(&self.path, contents).expect("Failed to write state file");
722	    }
723	
724	    pub fn add_task(&self, task: Task) {
725	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after = task.execute_after, "Scheduling task");
726	        let mut state = self.load();
727	        state.tasks.push(task);
728	        self.save(&state);
729	    }
730	
731	    pub fn remove_task(&self, task: &Task) {
732	        let mut state = self.load();
733	        state.tasks.retain(|t| !(t.epoch == task.epoch && t.kind.name() == task.kind.name()));
734	        self.save(&state);
735	    }
736	
737	    pub fn reschedule_task(&self, task: &Task, execute_after: u64) {
738	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after, "Rescheduling task");
739	        let mut state = self.load();
740	        for t in &mut state.tasks {
741	            if t.epoch == task.epoch && t.kind.name() == task.kind.name() {
742	                t.execute_after = execute_after;
743	                break;
744	            }
745	        }
746	        self.save(&state);
747	    }
748	
749	    /// Record the nonce and fees a transaction went out with.
750	    ///
751	    /// Written before the transaction is broadcast, so the record cannot be lost by a
752	    /// crash between broadcasting and persisting. A send that is then rejected outright
753	    /// leaves a harmless stale record: the next attempt simply sends at that nonce.
754	    pub fn set_pending_tx(&self, key: &str, nonce: u64, max_fee: u128, priority_fee: u128) {
755	        info!(logger = "TaskStore", route = self.label().as_str(), key, nonce, "Recording pending tx");
756	        let mut state = self.load();
757	        state.pending_txs.insert(key.to_string(), PendingTx { nonce, max_fee, priority_fee, tx_hash: None });
758	        self.save(&state);
759	    }
760	
761	    /// Attach the hash of the transaction just broadcast at this key's nonce.
762	    ///
763	    /// Written as a second step rather than as part of [`TaskStore::set_pending_tx`]
764	    /// because the hash only exists after the send, while the nonce has to be on disk
765	    /// before it. A replacement overwrites the hash: the record always describes the
766	    /// latest attempt at that nonce.
767	    pub fn set_pending_tx_hash(&self, key: &str, hash: FixedBytes<32>) {
768	        let mut state = self.load();
769	        match state.pending_txs.get_mut(key) {
770	            Some(pending) => pending.tx_hash = Some(hash),
771	            // Cleared underneath us (a concurrent `clear_pending_tx`); re-creating the
772	            // record from a hash alone would lose the nonce and fees it is built on.
773	            None => {
774	                warn!(logger = "TaskStore", route = self.label().as_str(), key, "No pending record to attach a tx hash to");
775	                return;
776	            }
777	        }
778	        self.save(&state);
779	    }
780	
781	    /// Forget a pending transaction, once its outcome is known.
782	    pub fn clear_pending_tx(&self, key: &str) {
783	        let mut state = self.load();
784	        state.pending_txs.remove(key);
785	        self.save(&state);
786	    }
787	
788	    pub fn get_pending_tx(&self, key: &str) -> Option<PendingTx> {
789	        self.load().pending_txs.get(key).cloned()
790	    }
791	
792	    pub fn update_inbox_block(&self, block: u64) {
793	        let mut state = self.load();
794	        state.inbox_last_block = Some(block);
795	        self.save(&state);
796	    }
797	
798	    pub fn update_outbox_block(&self, block: u64) {
799	        let mut state = self.load();
800	        state.outbox_last_block = Some(block);
801	        self.save(&state);
802	    }
803	
804	    pub fn set_indexing_since(&self, ts: u64) {
805	        let mut state = self.load();
806	        state.indexing_since = Some(ts);
807	        self.save(&state);
808	    }
809	
810	    pub fn initialize_sync(&self, indexing_since: u64, inbox_block: u64, outbox_block: u64) {
811	        let mut state = self.load();
812	        state.indexing_since = Some(indexing_since);
813	        state.inbox_last_block = Some(inbox_block);
814	        state.outbox_last_block = Some(outbox_block);
815	        self.save(&state);
816	    }
817	
818	    pub fn set_on_sync(&self, value: bool) {
819	        let mut state = self.load();
820	        state.on_sync = value;
821	        self.save(&state);
822	    }
823	
824	    pub fn is_on_sync(&self) -> bool {
825	        self.load().on_sync
826	    }
827	
828	    pub fn invalidate_tasks(&self, epoch: u64, kinds: &[&str]) {
829	        let mut state = self.load();
830	        let before = state.tasks.len();
831	        state.tasks.retain(|t| !(t.epoch == epoch && kinds.contains(&t.kind.name())));
832	        let removed = before - state.tasks.len();
833	        if removed > 0 {
834	            info!(logger = "TaskStore", route = self.label().as_str(), epoch, removed, "Invalidated tasks");
835	        }
836	        self.save(&state);
837	    }
838	
839	    pub fn set_last_saved_count(&self, count: u64) {
840	        let mut state = self.load();
841	        state.last_saved_count = Some(count);
842	        self.save(&state);
843	    }
844	
845	    pub fn get_last_saved_count(&self) -> Option<u64> {
846	        self.load().last_saved_count
847	    }
848	}
