851	    use alloy::primitives::U256;
852	    use serde::{self, Deserialize, Deserializer, Serializer};
853	
854	    pub fn serialize<S>(value: &U256, serializer: S) -> Result<S::Ok, S::Error>
855	    where
856	        S: Serializer,
857	    {
858	        serializer.serialize_str(&format!("{:#x}", value))
859	    }
860	
861	    pub fn deserialize<'de, D>(deserializer: D) -> Result<U256, D::Error>
862	    where
863	        D: Deserializer<'de>,
864	    {
865	        let s = String::deserialize(deserializer)?;
866	        U256::from_str_radix(s.trim_start_matches("0x"), 16).map_err(serde::de::Error::custom)
867	    }
868	}
869	
870	mod bytes_hex {
871	    use alloy::hex;
872	    use alloy::primitives::Bytes;
873	    use serde::{self, Deserialize, Deserializer, Serializer};
874	
875	    pub fn serialize<S>(value: &Bytes, serializer: S) -> Result<S::Ok, S::Error>
876	    where
877	        S: Serializer,
878	    {
879	        serializer.serialize_str(&format!("0x{}", hex::encode(value)))
880	    }
881	
882	    pub fn deserialize<'de, D>(deserializer: D) -> Result<Bytes, D::Error>
883	    where
884	        D: Deserializer<'de>,
885	    {
886	        let s = String::deserialize(deserializer)?;
887	        let bytes = hex::decode(s.trim_start_matches("0x")).map_err(serde::de::Error::custom)?;
888	        Ok(Bytes::from(bytes))
889	    }
890	}
