1	use alloy::primitives::{FixedBytes, U256};
2	use std::sync::{Arc, Mutex};
3	use tracing::{info, warn};
4	use crate::config::{Route, ValidatorConfig};
5	use crate::contracts::{IVeaInbox, IVeaOutbox, IVeaOutboxArbToEth, IVeaOutboxArbToGnosis};
6	use crate::finality::is_epoch_finalized;
7	use crate::tasks::{is_in_flight, send_or_replace, ClaimStore, Durability, TaskStore};
8	
9	const SEVEN_DAYS_SECS: u32 = 7 * 24 * 3600;
10	
11	pub async fn execute(
12	    config: &ValidatorConfig,
13	    route: &Route,
14	    epoch: u64,
15	    claim_store: &Arc<Mutex<ClaimStore>>,
16	    current_timestamp: u64,
17	    task_store: &Arc<Mutex<TaskStore>>,
18	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
19	    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
20	    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;
21	
22	    let finalized = is_epoch_finalized(
23	        epoch,
24	        epoch_period,
25	        &route.inbox_provider,
26	        &config.ethereum_provider,
27	        config.sequencer_inbox,
28	    ).await?;
29	    if !finalized {
30	        warn!(logger = "Claim", route = route.name, epoch, "Epoch not yet finalized on L1");
31	        return Err("EpochNotFinalized".into());
32	    }
33	
34	    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());
35	
36	    let state_root = inbox.snapshots(U256::from(epoch)).call().await?;
37	    if state_root == FixedBytes::<32>::ZERO {
38	        info!(logger = "Claim", route = route.name, epoch, "No snapshot");
39	        return Ok(());
40	    }
41	
42	    let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
43	    if claim_hash != FixedBytes::<32>::ZERO {
44	        info!(logger = "Claim", route = route.name, epoch, "Already claimed");
45	        return Ok(());
46	    }
47	
48	    let current_state_root = outbox.stateRoot().call().await?;
49	    if current_state_root == state_root {
50	        info!(logger = "Claim", route = route.name, epoch, "State root already verified on outbox");
51	        return Ok(());
52	    }
53	
54	    let since = (current_timestamp as u32).saturating_sub(SEVEN_DAYS_SECS);
55	    if claim_store.lock().unwrap().has_state_root_in_recent_claims(state_root, since) {
56	        info!(logger = "Claim", route = route.name, epoch, "State root already in pending claim");
57	        return Ok(());
58	    }
59	
60	    let wallet_address = config.wallet.default_signer().address();
61	    // The one write that is not gated on durability, because a gate here would have no
62	    // effect: claiming is driven by `EpochWatcher`, not by a task, and its very next cycle
63	    // re-enters this function and returns at the "Already claimed" check above - long
64	    // before a claim of ours could be final. All the gate would leave behind is a pending
65	    // record that nothing ever clears, one per epoch, forever.
66	    //
67	    // The watcher keeps `claim` honest a different way: it re-derives everything from the
68	    // chain on every pass, so a claim reorged out before the watcher has moved on is
69	    // simply re-sent.
70	    let durability = Durability::Confirmed;
71	    let result = if route.weth_address.is_some() {
72	        let gnosis_outbox = IVeaOutboxArbToGnosis::new(route.outbox_address, route.outbox_provider.clone());
73	        send_or_replace(
74	            gnosis_outbox.claim(U256::from(epoch), state_root),
75	            &route.outbox_provider,
76	            wallet_address,
77	            task_store,
78	            epoch,
79	            "claim",
80	            route.name,
81	            &durability,
82	        ).await
83	    } else {
84	        let eth_outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
85	        let deposit = eth_outbox.deposit().call().await?;
86	        send_or_replace(
87	            eth_outbox.claim(U256::from(epoch), state_root).value(deposit),
88	            &route.outbox_provider,
89	            wallet_address,
90	            task_store,
91	            epoch,
92	            "claim",
93	            route.name,
94	            &durability,
95	        ).await
96	    };
97	
98	    if let Err(e) = result {
99	        // Still in flight - not a failed claim, so don't consult the chain or the
100	        // caller will read "not claimed yet" and treat it as something to retry fresh.
101	        if is_in_flight(e.as_ref()) {
102	            return Err(e);
103	        }
104	        let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
105	        if claim_hash != FixedBytes::<32>::ZERO {
106	            info!(logger = "Claim", route = route.name, epoch, "Already claimed by another validator");
107	            return Ok(());
108	        }
109	        return Err(e);
110	    }
111	    Ok(())
112	}
