#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::{Fault, FaultTransport, block};
    use alloy::consensus::{Receipt, ReceiptEnvelope, ReceiptWithBloom};

    const TX_HASH: FixedBytes<32> = FixedBytes([0xAB; 32]);
    const RECEIPT_BLOCK: u64 = 100;

    /// A receipt as an endpoint would serve it: mined in [`RECEIPT_BLOCK`], `status` telling
    /// success from revert.
    fn receipt_json(status: bool) -> serde_json::Value {
        let receipt = alloy::rpc::types::TransactionReceipt {
            inner: ReceiptEnvelope::Eip1559(ReceiptWithBloom {
                receipt: Receipt { status: status.into(), cumulative_gas_used: 21_000, logs: vec![] },
                logs_bloom: Default::default(),
            }),
            transaction_hash: TX_HASH,
            transaction_index: Some(0),
            block_hash: Some(FixedBytes::from(U256::from(RECEIPT_BLOCK))),
            block_number: Some(RECEIPT_BLOCK),
            gas_used: 21_000,
            effective_gas_price: 1,
            blob_gas_used: None,
            blob_gas_price: None,
            from: Address::ZERO,
            to: None,
            contract_address: None,
        };
        serde_json::to_value(&receipt).expect("receipt is serializable")
    }

    /// An endpoint answering the two questions the durability gate asks: "is there a receipt
    /// for this hash" and "where is your `finalized` tag".
    ///
    /// `receipt` of `None` is the reorged-out case - a node that has no receipt answers
    /// `"result": null`, not an error.
    fn chain(receipt: Option<serde_json::Value>, finalized_block: u64) -> FaultTransport {
        FaultTransport::new(move |call| match call.method.as_str() {
            "eth_getTransactionReceipt" => match &receipt {
                Some(receipt) => Fault::Ok(receipt.clone()),
                None => Fault::null(),
            },
            "eth_getBlockByNumber" => Fault::Ok(block(finalized_block, 1_700_000_000)),
            _ => Fault::null(),
        })
    }

    fn store_with_pending(dir: &std::path::Path, key: &str) -> Arc<Mutex<TaskStore>> {
        let store = TaskStore::new(dir.join("sched.json"));
        store.set_pending_tx(key, 47, 30_000_000_000, 1_500_000_000);
        store.set_pending_tx_hash(key, TX_HASH);
        Arc::new(Mutex::new(store))
    }

    // -----------------------------------------------------------------------
    // mined but not durable: the task has to stay alive
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn a_mined_but_unfinalized_receipt_awaits_finality() {
        // Receipt in block 100, `finalized` still at 90: on chain, but a reorg could still
        // take it back.
        let transport = chain(Some(receipt_json(true)), RECEIPT_BLOCK - 10);
        let outcome = broadcast_outcome(
            &transport.provider(),
            TX_HASH,
            &Durability::ChainFinalized,
            "challenge",
            "ARB_TO_ETH",
        )
        .await;

        assert_eq!(outcome, MinedOutcome::AwaitFinality);
    }

    #[test]
    fn awaiting_finality_keeps_the_pending_record() {
        let dir = tempfile::tempdir().unwrap();
        let key = pending_key("challenge", 42);
        let task_store = store_with_pending(dir.path(), &key);

        let result = settle(&task_store, &key, MinedOutcome::AwaitFinality, "challenge", "ARB_TO_ETH");

        let err = result
            .expect("AwaitFinality resolves here - it must never fall through to the replacement path")
            .expect_err("a transaction that is not durable yet is not a success");
        assert_eq!(err.to_string(), AWAITING_FINALITY);
        // The caller returns this sentinel; both `dispatcher.rs` and the tasks' own
        // post-revert checks branch on it, so it must not read as "someone else did it".
        assert!(is_in_flight(err.as_ref()));

        // The record is what stops the next cycle from broadcasting or replacing anything:
        // `send_or_replace` looks the hash up first and settles on it again.
        let pending = task_store
            .lock()
            .unwrap()
            .get_pending_tx(&key)
            .expect("the pending record must survive, or the next cycle re-sends over a mined tx");
        assert_eq!(pending.nonce, 47);
        assert_eq!(pending.tx_hash, Some(TX_HASH));
    }

    // -----------------------------------------------------------------------
    // durable: done for good
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn a_finalized_receipt_settles() {
        // `finalized` has reached the receipt's own block, which is the bar.
        let transport = chain(Some(receipt_json(true)), RECEIPT_BLOCK);
        let outcome = broadcast_outcome(
            &transport.provider(),
            TX_HASH,
            &Durability::ChainFinalized,
            "challenge",
            "ARB_TO_ETH",
        )
        .await;

        assert_eq!(outcome, MinedOutcome::Settled);
    }

    #[test]
    fn settling_clears_the_pending_record() {
        let dir = tempfile::tempdir().unwrap();
        let key = pending_key("challenge", 42);
        let task_store = store_with_pending(dir.path(), &key);

        let result = settle(&task_store, &key, MinedOutcome::Settled, "challenge", "ARB_TO_ETH");

        assert!(result.expect("Settled resolves here").is_ok());
        assert!(
            task_store.lock().unwrap().get_pending_tx(&key).is_none(),
            "a durable write leaves nothing in flight; a kept record would pin a spent nonce"
        );
    }

    // -----------------------------------------------------------------------
    // reorged out before finality: re-send at the same nonce
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn a_missing_receipt_is_the_only_path_back_to_re_sending() {
        // The reorg case: we broadcast it, it was mined, and now the chain has no receipt
        // for it. Not durable, not done - it has to go out again.
        let transport = chain(None, RECEIPT_BLOCK);
        let outcome = broadcast_outcome(
            &transport.provider(),
            TX_HASH,
            &Durability::ChainFinalized,
            "challenge",
            "ARB_TO_ETH",
        )
        .await;

        assert_eq!(outcome, MinedOutcome::Resend);
    }

    #[test]
    fn resend_falls_through_with_the_nonce_intact() {
        let dir = tempfile::tempdir().unwrap();
        let key = pending_key("challenge", 42);
        let task_store = store_with_pending(dir.path(), &key);

        let result = settle(&task_store, &key, MinedOutcome::Resend, "challenge", "ARB_TO_ETH");

        assert!(
            result.is_none(),
            "Resend must not resolve: `None` is what sends `send_or_replace` on to the replacement path"
        );
        let pending = task_store
            .lock()
            .unwrap()
            .get_pending_tx(&key)
            .expect("the record must survive so the re-send reuses the same nonce");
        assert_eq!(pending.nonce, 47, "a fresh nonce here could double-spend the deposit");
    }

    #[tokio::test]
    async fn an_unreadable_receipt_waits_rather_than_re_sending() {
        // An endpoint that will not answer is not evidence that a transaction is absent.
        let transport = FaultTransport::new(|_| Fault::rate_limited());
        let outcome = broadcast_outcome(
            &transport.provider(),
            TX_HASH,
            &Durability::ChainFinalized,
            "challenge",
            "ARB_TO_ETH",
        )
        .await;

        assert_eq!(outcome, MinedOutcome::AwaitFinality);
    }

    #[tokio::test]
    async fn a_node_with_no_finalized_block_is_not_evidence_of_durability() {
        let transport = FaultTransport::new(move |call| match call.method.as_str() {
            "eth_getTransactionReceipt" => Fault::Ok(receipt_json(true)),
            // A node mid-sync answers `null` for a tag it cannot serve yet.
            "eth_getBlockByNumber" => Fault::null(),
            _ => Fault::null(),
        });
        let outcome = broadcast_outcome(
            &transport.provider(),
            TX_HASH,
            &Durability::ChainFinalized,
            "challenge",
            "ARB_TO_ETH",
        )
        .await;

        assert_eq!(outcome, MinedOutcome::AwaitFinality);
    }

    // -----------------------------------------------------------------------
    // the remaining outcomes
    // -----------------------------------------------------------------------

    #[test]
    fn mined_outcome_maps_every_receipt_shape() {
        assert_eq!(mined_outcome(None), MinedOutcome::Resend);
        assert_eq!(mined_outcome(Some((true, true))), MinedOutcome::Settled);
        assert_eq!(mined_outcome(Some((true, false))), MinedOutcome::AwaitFinality);
        // A revert is terminal whichever side of finality it is on: the nonce is spent.
        assert_eq!(mined_outcome(Some((false, false))), MinedOutcome::Reverted);
        assert_eq!(mined_outcome(Some((false, true))), MinedOutcome::Reverted);
    }

    #[test]
    fn a_revert_clears_the_record_and_is_not_in_flight() {
        let dir = tempfile::tempdir().unwrap();
        let key = pending_key("challenge", 42);
        let task_store = store_with_pending(dir.path(), &key);

        let err = settle(&task_store, &key, MinedOutcome::Reverted, "challenge", "ARB_TO_ETH")
            .expect("Reverted resolves here")
            .expect_err("a reverted transaction is a failure");

        // The caller's post-revert event checks have to run, so this must not look in-flight.
        assert!(!is_in_flight(err.as_ref()));
        assert!(
            task_store.lock().unwrap().get_pending_tx(&key).is_none(),
            "the nonce is consumed, so a retry needs a fresh one"
        );
    }

    #[test]
    fn is_in_flight_covers_both_sentinels_and_nothing_else() {
        let in_flight: [Box<dyn std::error::Error + Send + Sync>; 2] =
            ["PendingReplacement".into(), AWAITING_FINALITY.into()];
        for err in &in_flight {
            assert!(is_in_flight(err.as_ref()), "{err} means the transaction is still ours");
        }

        // Every other sentinel is a real outcome the caller has to act on.
        for msg in ["Insufficient funds", "NonceConsumed", "EpochNotFinalized", "Invalid claim."] {
            let err: Box<dyn std::error::Error + Send + Sync> = msg.into();
            assert!(!is_in_flight(err.as_ref()), "{msg} must not be mistaken for in-flight");
        }
    }

    #[test]
    fn block_is_finalized_treats_an_unanswered_tag_as_not_final() {
        assert!(block_is_finalized(100, Some(100)));
        assert!(block_is_finalized(100, Some(101)));
        assert!(!block_is_finalized(100, Some(99)));
        assert!(!block_is_finalized(100, None));
    }

    /// A pending record is read back from disk on every cycle, so the hash has to survive
    /// the round trip - lose it and `send_or_replace` has nothing to look up and re-sends
    /// over a transaction that may already be mined.
    #[test]
    fn pending_tx_hash_round_trips_through_json() {
        let pending = PendingTx {
            nonce: 47,
            max_fee: 30_000_000_000,
            priority_fee: 1_500_000_000,
            tx_hash: Some(TX_HASH),
        };

        let json = serde_json::to_string(&pending).expect("serializable");
        let back: PendingTx = serde_json::from_str(&json).expect("deserializable");

        assert_eq!(back.nonce, pending.nonce);
        assert_eq!(back.max_fee, pending.max_fee);
        assert_eq!(back.priority_fee, pending.priority_fee);
        assert_eq!(back.tx_hash, Some(TX_HASH));
    }
}

